import { FormEvent, useEffect, useState } from "react";
import { clubAdminRequest, uploadClubAdminImage } from "./api";
type Campaign = { id: string; title: string; active: boolean; points: number; media: Array<{ id: string; label: string; bannerId?: string; ready: boolean }> };
const channels = [{ id: "golbahar", label: "کلام تازه گلبهار" }, { id: "chenaran", label: "کلام تازه چناران" }, { id: "kalam", label: "کلام تازه (استانی و کشوری)" }];
export default function ClubCampaignAdmin({ initData }: { initData?: string }) {
  const [campaigns, setCampaigns] = useState<Campaign[]>([]); const [id, setId] = useState(""); const [title, setTitle] = useState("هدیه استوری باشگاه مخاطبان");
  const [active, setActive] = useState(false); const [banners, setBanners] = useState<Record<string, string>>({}); const [names, setNames] = useState<Record<string, string>>({}); const [busy, setBusy] = useState(false); const [notice, setNotice] = useState("");
  const refresh = async () => { try { const result = await clubAdminRequest<{ campaigns: Campaign[] }>(initData, "GET", "/api/admin/story-campaigns"); setCampaigns(result?.campaigns || []); } catch (e) { setNotice(e instanceof Error ? e.message : "دریافت کمپین‌ها ناموفق بود."); } };
  useEffect(() => { void refresh(); }, [initData]);
  const select = (value: string) => { setId(value); const campaign = campaigns.find(c => c.id === value); setTitle(campaign?.title || "هدیه استوری باشگاه مخاطبان"); setActive(campaign?.active || false); setBanners(Object.fromEntries(campaign?.media.map(m => [m.id, m.bannerId || ""]) || [])); setNames({}); setNotice(""); };
  const upload = async (channel: string, file?: File) => { if (!file) return; setBusy(true); setNotice(""); try { const result = await uploadClubAdminImage(initData, file, "campaign_banner"); if (!result) throw new Error("بارگذاری بنر انجام نشد."); setBanners(prev => ({ ...prev, [channel]: result.attachment.id })); setNames(prev => ({ ...prev, [channel]: file.name })); setNotice("بنر بارگذاری شد و در حال بررسی امنیتی است. برای ثبت تغییرات، ذخیره را بزنید."); } catch (e) { setNotice(e instanceof Error ? e.message : "بارگذاری ناموفق بود."); } finally { setBusy(false); } };
  const save = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setNotice(""); try { const result = await clubAdminRequest<{ campaign: Campaign }>(initData, id ? "PUT" : "POST", `/api/admin/story-campaigns${id ? `/${id}` : ""}`, { title, active, media: Object.fromEntries(channels.map(c => [c.id, { banner_id: banners[c.id] || null }])) }); if (!result) throw new Error("ذخیره انجام نشد."); setId(result.campaign.id); await refresh(); setNotice("کمپین ذخیره شد. بنرها پس از بررسی امنیتی قابل دریافت خواهند بود."); } catch (e) { setNotice(e instanceof Error ? e.message : "ذخیره کمپین ناموفق بود."); } finally { setBusy(false); } };
  return <section className="club-campaign-admin"><h3>هدیه استوری و بنرهای کمپین</h3><p className="hint">۱۵ امتیاز پس از تأیید اسکرین‌شات؛ برای هر مخاطب یک‌بار در هر کمپین. تغییر بنر، سهمیه هدیه را دوباره باز نمی‌کند. برای دور جدید، کمپین تازه بسازید.</p><form onSubmit={save}><label>انتخاب کمپین<select value={id} disabled={busy} onChange={e => select(e.target.value)}><option value="">＋ کمپین تازه</option>{campaigns.map(c => <option key={c.id} value={c.id}>{c.title} · {c.active ? "فعال" : "غیرفعال"}</option>)}</select></label><label>عنوان کمپین<input required value={title} disabled={busy} onChange={e => setTitle(e.target.value)} /></label><div className="club-campaign-banners">{channels.map(channel => <label key={channel.id}>{channel.label}<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onChange={e => void upload(channel.id, e.target.files?.[0])} /><small>{names[channel.id] || (banners[channel.id] ? "بنر ثبت شده؛ برای تغییر، فایل تازه انتخاب کنید." : "هنوز بنری انتخاب نشده است.")}</small></label>)}</div><label className="checkbox-row"><input type="checkbox" checked={active} disabled={busy} onChange={e => setActive(e.target.checked)} />نمایش هدیه به مخاطبان</label><button className="primary" disabled={busy}>{busy ? "در حال انجام…" : "ذخیره کمپین"}</button>{notice && <p className="notice" role="status">{notice}</p>}</form></section>;
}
